import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const VisibleEdgesMaterial = {
  uniforms: {
    color: { value: new THREE.Color(0xffffff) },
    opacity: { value: 1.0 }
  },
  vertexShader: `
    uniform vec3 color;
    varying vec3 vViewPosition;
    varying vec3 vNormal;

    void main() {
      vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
      vViewPosition = -mvPosition.xyz;
      vNormal = normalMatrix * normal;
      gl_Position = projectionMatrix * mvPosition;
    }
  `,
  fragmentShader: `
    uniform vec3 color;
    uniform float opacity;
    varying vec3 vViewPosition;
    varying vec3 vNormal;

    void main() {
      // Check if the edge is facing the camera
      vec3 viewNormal = normalize(vNormal);
      vec3 viewDirection = normalize(vViewPosition);

      // Only render if the surface is not facing away from the camera
      float edgeIntensity = abs(dot(viewNormal, viewDirection));

      // Higher threshold means fewer visible edges
      if (edgeIntensity > 0.2) {
        discard;
      }

      gl_FragColor = vec4(color, opacity);
    }
  `
};

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);
  const { camera } = useThree();

  useEffect(() => {
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => {
        // Calculate the bounding box to understand model size
        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);

        // Scale the model proportionally
        const scaleFactor = 2.5 / maxDimension;
        obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

        // Center the model
        box.setFromObject(obj);
        const center = box.getCenter(new THREE.Vector3());
        obj.position.sub(center);

        // Create custom material for edges
        const edgeMaterial = new THREE.ShaderMaterial({
          uniforms: THREE.UniformsUtils.clone(VisibleEdgesMaterial.uniforms),
          vertexShader: VisibleEdgesMaterial.vertexShader,
          fragmentShader: VisibleEdgesMaterial.fragmentShader,
          transparent: true,
          side: THREE.FrontSide
        });

        // Replace meshes with visible edge lines
        obj.traverse((child) => {
          if (child.isMesh) {
            // Create edges geometry
            const edges = new THREE.EdgesGeometry(child.geometry, 45);
            const edgeLines = new THREE.LineSegments(edges, edgeMaterial);

            // Copy transformations from the original mesh
            edgeLines.position.copy(child.position);
            edgeLines.rotation.copy(child.rotation);
            edgeLines.scale.copy(child.scale);

            // Replace the original mesh with edge lines
            child.parent.add(edgeLines);
            child.parent.remove(child);
          }
        });

        // If groupRef exists, add the model to it
        if (groupRef.current) {
          groupRef.current.add(obj);
        }
        setModel(obj);
      },
      undefined,
      (error) => {
        console.error('Error loading OBJ:', error);
      }
    );
  }, [modelPath]);

  // Rotate around the center
  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
    </group>
  );
};

const App = () => {
  const modelPath = require('./stls/model.obj');

  return (
    <div style={{ height: '100vh', margin: 0 }}>
      <h1 style={{ position: 'absolute', color: 'white', top: '10px', left: '10px', zIndex: 10 }}>
        3D Model Viewer
      </h1>
      <Canvas
        style={{ backgroundColor: 'black' }}
        camera={{ 
          position: [2.5, 2.5, 2.5],
          fov: 45,
        }}
      >
        {/* Lights */}
        <ambientLight intensity={0.5} />
        <spotLight position={[10, 10, 10]} intensity={1} />
        <directionalLight position={[5, 5, 5]} intensity={1} />

        {/* Model loader */}
        <ModelLoader modelPath={modelPath} />

        {/* Orbit controls with limited rotation and no zoom */}
        <OrbitControls 
          enableZoom={false}
          minPolarAngle={Math.PI / 4}
          maxPolarAngle={Math.PI / 4}
          minAzimuthAngle={-Math.PI / 4}
          maxAzimuthAngle={Math.PI / 4}
        />
      </Canvas>
    </div>
  );
};

export default App;
